<script setup lang="ts">import{onMounted,ref}from'vue';import{request}from'../api/client';interface Moment{id:number;nickname:string;username:string;content:string;media:unknown[];status:string;created_at:string}const items=ref<Moment[]>([]),selected=ref<Moment|null>(null),approve=ref(true),reason=ref('');async function load(){items.value=await request<Moment[]>('/v1/moments/?status=pending')}async function submit(){if(!selected.value)return;await request(`/v1/moments/${selected.value.id}/decision`,{method:'POST',body:JSON.stringify({approve:approve.value,reason:reason.value})});selected.value=null;await load()}onMounted(load)</script><template><div class="page"><div class="heading"><div><h1>朋友圈审核</h1><p>待发布内容的人工审核队列</p></div><button @click="load">刷新</button></div><div class="table"><table><thead><tr><th>发布者</th><th>内容</th><th>媒体</th><th>时间</th><th></th></tr></thead><tbody><tr v-for="m in items" :key="m.id"><td>{{m.nickname}}<small>@{{m.username}}</small></td><td class="content">{{m.content||'-'}}</td><td>{{m.media?.length??0}} 项</td><td>{{new Date(m.created_at).toLocaleString()}}</td><td><button class="link" @click="selected=m;approve=true;reason=''">审核</button></td></tr></tbody></table></div><div v-if="selected" class="backdrop" @click.self="selected=null"><form class="dialog" @submit.prevent="submit"><h2>审核动态</h2><label>结果<select v-model="approve"><option :value="true">通过</option><option :value="false">拒绝</option></select></label><label>审核说明<textarea v-model.trim="reason" :required="!approve"></textarea></label><div class="actions"><button type="button" @click="selected=null">取消</button><button class="primary">提交</button></div></form></div></div></template><style scoped>@import '../design/admin-page.css';.content{max-width:420px;white-space:normal}</style>
